/*! نسخة مبسطة للتعامل مع التبديل في القائمة. يفضل استبدالها بملف Bootstrap الفعلي. */
(function(){
    document.addEventListener('click',function(e){
        var toggler = e.target.closest('[data-bs-toggle="collapse"]');
        if(!toggler){return;}
        var target = document.querySelector(toggler.getAttribute('data-bs-target'));
        if(target){
            target.classList.toggle('show');
        }
    });
})();
